{
  "name": "opencode-bifrost",
  "version": "3.2.8",
  "description": "OpenCode plugin for multi-server persistent SSH connections via ssh-agent",
  "author": "itsmylife44",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/itsmylife44/bifrost.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --format esm --target node && tsc --emitDeclarationOnly",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.27",
    "ssh2": "^1.17.0",
    "zod": "^4.3.6"
  },
  "devDependencies": {
    "@types/ssh2": "^1.15.5",
    "bun-types": "latest",
    "typescript": "^5.9.3"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "ssh",
    "ssh2",
    "cross-platform",
    "ocx"
  ],
  "engines": {
    "node": ">=18.0.0"
  }
}
